-- v0.4.0 태그의 코드가 Hibernate(ddl-auto)로 만든 H2 스키마(데이터 없음). 업그레이드 테스트의 시작 상태다.
-- 생성: 그 태그로 앱을 빈 H2 파일 DB에 띄운 뒤 org.h2.tools.Script -options NODATA 로 덤프하고 사용자 계정 줄을 뺐다.
;
CREATE CACHED TABLE "PUBLIC"."APP_USER"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "CREATED_AT" TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    "LOGIN_ID" CHARACTER VARYING(20) NOT NULL,
    "NICKNAME" CHARACTER VARYING(20) NOT NULL,
    "PASSWORD_HASH" CHARACTER VARYING(100) NOT NULL
);
ALTER TABLE "PUBLIC"."APP_USER" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_7" PRIMARY KEY("ID");
CREATE CACHED TABLE "PUBLIC"."BROADCAST"(
    "KIND" CHARACTER VARYING(20) NOT NULL,
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "CREATED_AT" TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    "TITLE" CHARACTER VARYING(100) NOT NULL,
    "OWNER_ID" BIGINT
);
ALTER TABLE "PUBLIC"."BROADCAST" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_459" PRIMARY KEY("ID");
CREATE CACHED TABLE "PUBLIC"."BROADCAST_COMMENT"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "CONTENT" CHARACTER VARYING(300) NOT NULL,
    "CREATED_AT" TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    "AUTHOR_ID" BIGINT NOT NULL,
    "BROADCAST_ID" BIGINT NOT NULL
);
ALTER TABLE "PUBLIC"."BROADCAST_COMMENT" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_1" PRIMARY KEY("ID");
CREATE CACHED TABLE "PUBLIC"."DONATION"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "AMOUNT" BIGINT NOT NULL,
    "CONFIRMED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "CREATED_AT" TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    "FAILURE_CODE" CHARACTER VARYING(255),
    "MESSAGE" CHARACTER VARYING(200),
    "ORDER_ID" CHARACTER VARYING(64) NOT NULL,
    "PAYMENT_KEY" CHARACTER VARYING(255),
    "STATUS" ENUM('CANCELED', 'CONFIRMED', 'FAILED', 'PENDING') NOT NULL,
    "BROADCAST_ID" BIGINT NOT NULL,
    "DONOR_ID" BIGINT NOT NULL,
    "RECIPIENT_ID" BIGINT NOT NULL
);
ALTER TABLE "PUBLIC"."DONATION" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_73" PRIMARY KEY("ID");
CREATE CACHED TABLE "PUBLIC"."LIVE_BROADCAST"(
    "ENDED_AT" TIMESTAMP(6) WITH TIME ZONE,
    "STATUS" ENUM('ENDED', 'ON_AIR') NOT NULL,
    "STREAM_KEY_HASH" CHARACTER VARYING(64) NOT NULL,
    "THUMBNAIL_KEY" CHARACTER VARYING(255),
    "ID" BIGINT NOT NULL
);
ALTER TABLE "PUBLIC"."LIVE_BROADCAST" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_B" PRIMARY KEY("ID");
CREATE CACHED TABLE "PUBLIC"."RECORDING_BROADCAST"(
    "ID" BIGINT NOT NULL,
    "VIDEO_ID" BIGINT NOT NULL
);
ALTER TABLE "PUBLIC"."RECORDING_BROADCAST" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_E" PRIMARY KEY("ID");
CREATE CACHED TABLE "PUBLIC"."VIDEO"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1) NOT NULL,
    "DURATION_SECONDS" FLOAT(53),
    "CONTENT_TYPE" CHARACTER VARYING(100) NOT NULL,
    "ORIGINAL_FILENAME" CHARACTER VARYING(255) NOT NULL,
    "SIZE_BYTES" BIGINT NOT NULL,
    "STORAGE_KEY" CHARACTER VARYING(255) NOT NULL,
    "THUMBNAIL_KEY" CHARACTER VARYING(255)
);
ALTER TABLE "PUBLIC"."VIDEO" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_4DE" PRIMARY KEY("ID");
ALTER TABLE "PUBLIC"."BROADCAST" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_45" CHECK("KIND" IN('LIVE', 'RECORDING')) NOCHECK;
ALTER TABLE "PUBLIC"."VIDEO" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_4D" CHECK("CONTENT_TYPE" IN('video/webm', 'video/mp4')) NOCHECK;
